-- Integration assertions run within one rolled-back transaction. No email or payment calls.
begin;
do $$
declare actor uuid:=gen_random_uuid();artist uuid:=gen_random_uuid();stranger uuid:=gen_random_uuid();org uuid;ev uuid;tier uuid;a uuid;g uuid;g2 uuid;ord uuid;ticket uuid;rid uuid:=gen_random_uuid();q jsonb;change public.sb_capacity_changes;result text;
begin
 insert into auth.users(id,email,email_confirmed_at) values(actor,'owner-'||actor||'@example.test',now()),(artist,'artist-'||artist||'@example.test',now()),(stranger,'stranger-'||stranger||'@example.test',now());
 insert into public.sb_event_organisers(owner_user_id,display_name,country_code,status,stripe_account_id,stripe_capabilities_ready,tax_review_complete) values(actor,'Guest capacity QA','PT','approved','acct_qa_no_network',true,true) returning id into org;
 insert into public.sb_events(slug,title,organiser_profile_id,status,starts_at,ends_at) values('guest-qa-'||gen_random_uuid()::text,'Guest Capacity QA',org,'draft',now()+interval '2 hours',now()+interval '8 hours') returning id into ev;
 insert into public.sb_event_tiers(event_id,name,price_cents,quantity_total) values(ev,'General',2000,90) returning id into tier;
 insert into public.sb_event_listing_fees(event_id,organiser_profile_id,tier_code,amount_cents,currency,status) values(ev,org,'starter',5900,'eur','paid');
 update public.sb_events set status='published' where id=ev;
 execute 'set local role service_role';
 a:=public.sb_manage_guest_allocation(actor,ev,tier,'QA DJ','artist-'||artist||'@example.test',10);
 if public.sb_guest_reserved(tier)<>10 then raise exception 'Guest places not reserved';end if;
 begin perform public.sb_manage_guest_allocation(stranger,ev,tier,'Bad','bad@example.test',5);raise exception 'ASSERT unauthorized allocation';exception when others then if SQLERRM like 'ASSERT%' then raise;end if;end;
 begin perform public.sb_manage_guest_allocation(actor,ev,tier,'Over','over@example.test',81);raise exception 'ASSERT over-allocation';exception when others then if SQLERRM like 'ASSERT%' then raise;end if;end;
 begin perform public.sb_issue_guest_pass(a,stranger,'stranger-'||stranger||'@example.test','Guest','guest@example.test',rid);raise exception 'ASSERT wrong artist';exception when others then if SQLERRM like 'ASSERT%' then raise;end if;end;
 g:=public.sb_issue_guest_pass(a,artist,'artist-'||artist||'@example.test','Guest One','guest@example.test',rid);
 g2:=public.sb_issue_guest_pass(a,artist,'artist-'||artist||'@example.test','Guest One','guest@example.test',rid);
 if g<>g2 or public.sb_guest_reserved(tier)<>9 then raise exception 'Guest retry not idempotent';end if;
 select order_id into ord from public.sb_guest_entries where id=g;
 if (select total_cents from public.sb_event_orders where id=ord)<>0 then raise exception 'Guest charged';end if;
 perform public.sb_manage_guest_allocation(actor,ev,tier,'QA DJ','artist-'||artist||'@example.test',1,a);
 begin perform public.sb_issue_guest_pass(a,artist,'artist-'||artist||'@example.test','Guest Two','guest2@example.test',gen_random_uuid());raise exception 'ASSERT quota exceeded';exception when others then if SQLERRM like 'ASSERT%' then raise;end if;end;
 select id into ticket from public.sb_event_tickets where order_id=ord;
 if public.sb_checkin_event_ticket(ticket,actor)->>'status'<>'valid' then raise exception 'Guest scan failed';end if;
 if public.sb_checkin_event_ticket(ticket,actor)->>'status'<>'used' then raise exception 'Guest reused';end if;
 update public.sb_event_orders set status='cancelled' where id=ord;
 if public.sb_checkin_event_ticket(ticket,actor)->>'status'<>'invalid' then raise exception 'Cancelled guest accepted';end if;
 perform public.sb_manage_guest_allocation(actor,ev,tier,'QA DJ','artist-'||artist||'@example.test',1,a,true);
 if public.sb_guest_reserved(tier)<>0 then raise exception 'Revoke did not release unused places';end if;
 q:=public.sb_capacity_quote(actor,ev,tier,100);
 if (q->>'amountCents')::int<>0 then raise exception 'Within band charged';end if;
 change:=public.sb_prepare_capacity_change(actor,ev,tier,100,0);
 if change.status<>'applied' or (select quantity_total from public.sb_event_tiers where id=tier)<>100 then raise exception 'Free increase failed';end if;
 q:=public.sb_capacity_quote(actor,ev,tier,500);
 if (q->>'amountCents')::int<>6000 then raise exception 'Wrong difference';end if;
 change:=public.sb_prepare_capacity_change(actor,ev,tier,500,6000);
 if (select quantity_total from public.sb_event_tiers where id=tier)<>100 then raise exception 'Unpaid increase released';end if;
 update public.sb_capacity_changes set stripe_session_id='cs_qa_'||change.id where id=change.id;
 begin perform public.sb_apply_capacity_payment(change.id,'wrong',6000,'eur');raise exception 'ASSERT wrong payment accepted';exception when others then if SQLERRM like 'ASSERT%' then raise;end if;end;
 result:=public.sb_apply_capacity_payment(change.id,'cs_qa_'||change.id,6000,'eur');
 if result<>'applied' or (select quantity_total from public.sb_event_tiers where id=tier)<>500 then raise exception 'Verified increase failed';end if;
 if public.sb_apply_capacity_payment(change.id,'cs_qa_'||change.id,6000,'eur')<>'applied' then raise exception 'Payment retry failed';end if;
 q:=public.sb_capacity_quote(actor,ev,tier,501);
 if (q->>'amountCents')::int<>12000 then raise exception 'Already paid band not credited';end if;
 a:=public.sb_manage_guest_allocation(actor,ev,tier,'Alert DJ','alert@example.test',400);
 perform public.sb_generate_capacity_alerts();perform public.sb_generate_capacity_alerts();
 if (select count(*) from public.sb_capacity_alerts where event_id=ev and threshold=80)<>1 then raise exception 'Alert missing or duplicated';end if;
 if (select count(*) from public.portal_notifications where user_id=actor and title like 'Ticket capacity:%')<>1 then raise exception 'Organiser notification missing';end if;
 if has_table_privilege('authenticated','public.sb_guest_entries','SELECT') or has_function_privilege('anon','public.sb_apply_capacity_payment(uuid,text,integer,text)','EXECUTE') then raise exception 'Public access to private data';end if;
end $$;
rollback;
